import from "@mui/icons-material/MoreVert" { default as MoreVertIcon }
import from "@mui/material" { Box, IconButton, ListItem, ListItemButton, Typography }
import from "@/shared/constants" { actionMenuIds }
import from "@/shared/lib/browser" { openNewTab }
import from "../BookmarkIcon.jac" { BookmarkIcon as BookmarkIcon }

def _emptyFunc(e: object = None, nodeId: object = None, menuId: str = "") -> None {
}

def:pub FileListItem(props: dict[str, object]) -> JsxElement {
    itemNode = {"id": "", "url": "", "title": ""};
    if "node" in props {
        itemNode = props["node"] as dict[str, str];
    }
    iconSize = 24;
    if "iconSize" in props {
        iconSize = props["iconSize"] as int;
    }
    selected = False;
    if "selected" in props {
        selected = props["selected"] as bool;
    }
    onDragStart = _emptyFunc;
    if "onDragStart" in props {
        onDragStart = props["onDragStart"] as Callable[[object, object], None];
    }
    onClick = _emptyFunc;
    if "onClick" in props {
        onClick = props["onClick"] as Callable[[object, object], None];
    }
    onRightClick = _emptyFunc;
    if "onRightClick" in props {
        onRightClick = props["onRightClick"] as Callable[[object, object, str], None];
    }
    onActionMenuClick = _emptyFunc;
    if "onActionMenuClick" in props {
        onActionMenuClick = props["onActionMenuClick"] as Callable[[object, object, str], None];
    }
    draggable = bool(onDragStart);
    nodeId = itemNode["id"];
    menuId = f"bookmark-file-action-menu-{nodeId}";
    def handleActionMenuClick(e: MouseEvent) {
        onActionMenuClick(e, nodeId, actionMenuIds.fileActionMenuId);
    }
    def handleContextMenu(e: MouseEvent) {
        onRightClick(e, nodeId, actionMenuIds.fileActionMenuId);
    }
    def handleDoubleClick(e: MouseEvent) {
        openNewTab(itemNode["url"]);
    }
    def handleDragStart(e: object) {
        onDragStart(e, nodeId);
    }
    def handleClick(e: MouseEvent) {
        onClick(e, nodeId);
    }
    return <ListItem disablePadding secondaryAction={<IconButton edge="end" aria-label="more actions" aria-controls={menuId} aria-haspopup="true" aria-expanded="false" onClick={handleActionMenuClick}><MoreVertIcon /></IconButton>}><ListItemButton draggable={draggable} selected={selected} onDragStart={handleDragStart} onClick={handleClick} onContextMenu={handleContextMenu} onDoubleClick={handleDoubleClick}><BookmarkIcon url={itemNode["url"]} size={iconSize} /><Box sx={{"ml": 1, "overflow": "hidden"}}><Typography variant="body2" noWrap>{itemNode["title"]}</Typography></Box></ListItemButton></ListItem>;
}
