import from "lodash/get" { default as get }

obj OptionConfig {
    has key: str;
    has label: str;
    has value: str | None = None;
}

def:pub getOptionFromConfig[T](option: T, config: OptionConfig | None = None) -> dict[str, object] {
    if config {
        return {
            "key": String(get(option, config.key)),
            "value": (get(option, config.value) if config.value else option),
            "label": String(get(option, config.label)),
        };
    }
    return {"key": String(option), "value": option, "label": String(option)};
}

def:pub getSelectOptionFromConfig[T](option: T, config: OptionConfig | None = None) -> dict[str, object] {
    if config {
        return {
            "key": String(get(option, config.key)),
            "value": String((get(option, config.value) if config.value else option)),
            "label": String(get(option, config.label)),
        };
    }
    return {"key": String(option), "value": String(option), "label": String(option)};
}
