import from core.entities.PlayerMark { PlayerMark }

obj Entry {
    has text: str;
    has squares: list[PlayerMark | None];
    has currentPlayer: PlayerMark;
}

obj History {
    has squares_seed: list[PlayerMark | None];
    has value: list[Entry] postinit;

    def postinit {
        self.value = [
            Entry(
                text="Go to game start",
                squares=self.squares_seed,
                currentPlayer="X"
            )
        ];
    }

    def add(squares: list[PlayerMark | None], currentPlayer: PlayerMark) {
        text = "Go to game start" if self.is_empty() else f"Go to move #{self.size()}";
        self.value = self.value + [
            Entry(text=text, squares=squares, currentPlayer=currentPlayer)
        ];
    }

    def size() -> int {
        return len(self.value);
    }

    def is_empty() -> bool {
        return len(self.value) == 0;
    }

    def goTo(index: int) {
        self.value = self.value[0:index + 1];
    }
}
