    has show: bool = False;

    import from "react" { useEffect, useRef }
    showRef = useRef(False);

    useEffect(lambda {
        if timerId is not None {
            clearTimeout(timerId);
        }
        if isVisible {
            showRef.current = True;
            show = True;
        } else {
            timerId = setTimeout(lambda { show = False; }, DELAY) as float;
        }
        return lambda {
            if timerId is not None {
                clearTimeout(timerId);
            }
        };
    }, [isVisible]);

    return {"show": show};
}
