import { isChineseLocale } from "@/app/utils";
import { TOOL_REGISTRY, TOOL_KEYS, toolPathsByGroup, type ToolKey } from "@/app/lib/toolRegistry";

// 子项目导航：本仓库对应的工具走相对首页 `/${locale}`，其余工具指向主站。
