def:pub isCompletelyVisible(element: HTMLElement) -> bool {
    if element.parentElement is None {
        raise ValueError("not a carousel slide");
    }
    slider = element.parentElement;
    elementBoundingRect = element.getBoundingClientRect();
    sliderBoundingRect = slider.getBoundingClientRect();
    sliderWidth = sliderBoundingRect.width;
    positionLeft = elementBoundingRect.left - sliderBoundingRect.left;
    positionRight = positionLeft + elementBoundingRect.width;
    return (positionLeft >= 0) and (positionRight <= sliderWidth);
}
