   */
  idleDuration: number;

  /**
   * Last activity timestamp
   */
  lastActivity: number;
}

const DEFAULT_THRESHOLD = 5 * 60 * 1000; // 5 minutes

/**
 * Hook for detecting user idle state
 */
export function useIdleDetection(config: IdleDetectionConfig): IdleDetectionState {
