import random;

def folder(id: str) -> dict[str, object] {
    return {"isFolder": True, "id": id, "parent": "root", "title": id, "content": ""};
}

def file(id: str, parent: str) -> dict[str, object] {
    return {"isFolder": False, "id": id, "parent": parent, "title": id, "content": f"<h1>{id}</h1><hr/><p>内容内容内容{random.random()}</p>"};
}

def randomInt(min: int, max: int) -> int {
    return random.randint(min, max);
}

def generateFolders(num: int) -> list[dict[str, object]] {
    return [folder(f"folder__{index + 1}") for index in range(max(1, num))];
}

def generateFiles(num: int) -> list[dict[str, object]] {
    arr: list[dict[str, object]] = [];
    for el in mockFolders {
        for index in range(randomInt(1, max(1, num))) {
            arr = arr + [file(f"file[{el['id']}]__{index + 1}", el["id"] as str)];
        }
    }
    return arr;
}

glob mockFolders: list[dict[str, object]] = generateFolders(50);
glob mockFiles: list[dict[str, object]] = generateFiles(100);
glob:pub fakeData: list[dict[str, object]] = mockFolders + mockFiles;
