    if ((("spreadsheet" in fileType) or ("excel" in fileType)) or (fileType == "text/csv")) {
        return "📊";
    }
    if (((("zip" in fileType) or ("tar" in fileType)) or ("rar" in fileType)) or ("gz" in fileType)) {
        return "📦";
    }
    if ((((("javascript" in fileType) or ("typescript" in fileType)) or ("python" in fileType)) or ("java" in fileType)) or ("cpp" in fileType)) {
        return "💻";
    }
    return "📎";
}

