import from random { choice }
import from time { time }
import from ...services.storage { getFromStorage, saveToStorage }

glob MEETINGS_KEY = "MEETINGS";

def:pub useMeetings() -> dict[str, object] {
    has meetings: list[dict[str, str]] = [];

    def createNewMeeting() {
        code = getRandomCode();
        meeting = {"code": code, "timestamp": str(int(time()))};
        meetings = meetings + [meeting];
        saveToStorage(MEETINGS_KEY, meetings);
    }

    def removeMeeting(meeting: dict[str, str]) {
        code = meeting["code"];
        stored = getFromStorage(MEETINGS_KEY) or [];
        filteredMeetings = [m for m in stored if m["code"] != code];
        saveToStorage(MEETINGS_KEY, filteredMeetings);
        meetings = filteredMeetings;
    }

    return {
        "meetings": meetings,
        "createNewMeeting": createNewMeeting,
        "removeMeeting": removeMeeting,
    };
}

def getRandomCode() -> str {
    chars = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ";
    def threeLengthCode() -> str {
        return f"{choice(chars)}{choice(chars)}{choice(chars)}";
    }
    return f"{threeLengthCode()}-{threeLengthCode()}-{threeLengthCode()}";
}
