      const node = state.directory.folderMetadata[nodeId]
      if(node && node.parentId === folderMetadata.id) {
        content.push(node)
      }
    }

    for (const nodeId in state.directory.fileMetadata) {
      const node = state.directory.fileMetadata[nodeId]
      if(node && node.parentId === folderMetadata.id) {
        content.push(node)
      }
    }

