) -> TAsyncTuple[ErrorType, DataType] {
    try {
        data = await promise();
        return TAsyncTuple[ErrorType, DataType](error=None, data=data);
    } except Exception as caught {
        print(caught);
        return TAsyncTuple[ErrorType, DataType](error=caught as ErrorType, data=None);
