    stacktrace = getattr(error, "stacktrace", None);
    opera_src = getattr(error, "opera#sourceloc", None);
    if stacktrace is not None or opera_src is not None {
        st = stacktrace if stacktrace is not None else "";
        return [line for line in str(st).split("\n") if line != ""];
    }
