import pycountry;

obj IsoCodeEntry {
    has countryId: str;
    has isoAlpha3: str;
}

def:pub toAlpha2(isoAlpha3: str) -> str | None {
    country = pycountry.countries.get(alpha_3=isoAlpha3.upper());
    if country is None {
        return None;
    }
    return country.alpha_2;
}

def:pub buildCountryIdByAlpha2(isoCodes: list[IsoCodeEntry]) -> dict[str, str] {
    result: dict[str, str] = {};
    for entry in isoCodes {
        alpha2 = toAlpha2(entry.isoAlpha3);
        if alpha2 {
            result[alpha2] = entry.countryId;
        }
    }
    return result;
}
