```jac
def:pub Tab(
    children: JsxElement | str | None = None,
    className: str = "",
    indicatorClass: str = "",
    renderIndicator: Callable[[bool], JsxElement | None] | None = None,
    id: str = "",
    selected: bool = False,
    onClick: Callable[[MouseEvent], None] | None = None,
) -> JsxElement {
    def _renderIndicator() -> JsxElement | None {
        if not selected {
            return None;
        }
        if renderIndicator {
            return renderIndicator(selected);
        }
        return <div className={"absolute inset-x-0 -bottom-1 border border-dd-primary " + indicatorClass} />;
    }

    def handle_click(e: MouseEvent) {
        if onClick {
            onClick(e);
        }
    }

    selectedClass = "text-dd-primary" if selected else "";
    mergedClass = (selectedClass + " relative flex cursor-pointer items-center justify-center text-xl hover:opacity-70 " + className).strip();

    return <div className={mergedClass} onClick={handle_click}>
        {children}
        {_renderIndicator()}
    </div>;
}
