}

const Item: React.FC<TabBarItemProps> = props => {

  const {
    className,
    icon,
    title,
    badge,
    dot,
    fkey,
    activeKey,
    selectedColor,
    onClick
  } = props;

  const isSelected = activeKey && activeKey === fkey ? true : false;
  const wrapCls = classnames(prefixCls, className, {
