import asyncio;

obj PromiseQueue[T] {
    has pending: asyncio.Task[T] | None = None;

    async def execute(fn: Callable[[], Awaitable[T]]) -> T {
        if self.pending is not None {
            return await self.pending;
        }
        task = asyncio.create_task(fn());
        self.pending = task;
        try {
            return await task;
        } finally {
            self.pending = None;
        }
    }

    def isExecuting() -> bool {
        return self.pending is not None;
    }
}
