def:pub HideDuring(props: HideDuringProps) -> JsxElement {
    showState = useState(False);
    setShow = showState[1];
    timeoutRef = useRef(None);

    listenToScroll = useCallback(lambda {
        setShow(not props.inverse);
        if timeoutRef.current {
            clearTimeout(timeoutRef.current);
        }
        timeoutRef.current = setTimeout(lambda {
            setShow(props.inverse);
        }, 100);
    }, [props.inverse]);

    useEffect(lambda {
        window.addEventListener("scroll", listenToScroll);
        return lambda { window.removeEventListener("scroll", listenToScroll); };
    }, [listenToScroll]);

    return <>{showState[0] and props.children}</>;
}
