interface FormRule {
  key: string;
  required?: boolean;
  minLength?: number;
  maxLength?: number;
  pattern?: RegExp;
}

export interface Errors {
  [k:string]: string[]
}

export type FormRules = Array<FormRule>

const isempty = (value: any): Boolean => {
  if (value === undefined || value === null || value === '') {
    return true;
  }
  return false;

