def:pub validateNoteTemplate(
    template: NoteTemplateInput,
    existingTemplates: list[NoteTemplateInput] | None = None
) -> ValidationResult {
    errors: list[str] = [];
    templates = existingTemplates if existingTemplates is not None else [];
    if template.name is None or len(template.name.strip()) == 0 {
        errors.append("Name is required");
    } else {
        if len(template.name) < 1 or len(template.name) > 100 {
            errors.append("Name must be between 1 and 100 characters");
        }
        nameLower = template.name.lower();
        isDuplicate = False;
        for t in templates {
            if t.id != template.id and t.name is not None and t.name.lower() == nameLower {
                isDuplicate = True;
                break;
            }
        }
        if isDuplicate {
            errors.append(f"Template with name \"{template.name}\" already exists");
        }
    }
    if template.description is None or len(template.description.strip()) == 0 {
        errors.append("Description is required");
    } else {
        if len(template.description) < 1 or len(template.description) > 50000 {
            errors.append("Description must be between 1 and 50000 characters");
        }
    }
    return ValidationResult(valid=len(errors) == 0, errors=errors);
}

