        className={`flex shrink-0 items-center justify-center rounded-full bg-surface font-bold text-muted ${textSize} ${sizeClass}`}
      >
        {initial}
      </div>
    );
  }

  return (
    <img
      src={src}
      alt={name}
      className={`shrink-0 rounded-full object-cover ${sizeClass}`}
      onError={() => setHasError(true)}
    />
  );
}
