import from "date-fns" { differenceInDays, addDays, startOfDay, endOfDay }

type ZoomLevel = str;

obj GanttTaskDates {
    has startDate: str | None = None;
    has dueDate: str | None = None;
}

glob:pub PIXELS_PER_DAY: dict[str, int] = {"day": 40, "week": 8, "month": 2};

glob:pub ROW_HEIGHT: int = 60;

glob:pub HEADER_HEIGHT: int = 50;

glob:pub TASK_BAR_HEIGHT: int = 40;

def:pub dateToX(date: object, scaleStart: object, zoom: ZoomLevel) -> float {
    daysDiff = differenceInDays(startOfDay(date), startOfDay(scaleStart));
    return (daysDiff * PIXELS_PER_DAY[zoom]);
}

def:pub xToDate(x: float, scaleStart: object, zoom: ZoomLevel) -> object {
    days = Math.round((x / PIXELS_PER_DAY[zoom]));
    return addDays(scaleStart, days);
}

def:pub calculateBarWidth(startDate: object, endDate: object, zoom: ZoomLevel) -> float {
    days = differenceInDays(endOfDay(endDate), startOfDay(startDate));
    return (Math.max((days + 1), 1) * PIXELS_PER_DAY[zoom]);
}

def:pub getTimelineBounds(tasks: list[GanttTaskDates]) -> dict[str, object] {
    dates: list[object] = [];
    for task in tasks {
        if task.startDate {
            dates.append(new(Date, task.startDate));
        }
        if task.dueDate {
            dates.append(new(Date, task.dueDate));
        }
    }
    if len(dates) == 0 {
        today = new(Date);
        return {"start": addDays(today, -15), "end": addDays(today, 15)};
    }
    minDate = dates[0];
    maxDate = dates[0];
    for d in dates[1:] {
        if differenceInDays(startOfDay(d), startOfDay(minDate)) < 0 {
            minDate = d;
        }
        if differenceInDays(startOfDay(d), startOfDay(maxDate)) > 0 {
            maxDate = d;
        }
    }
    return {"start": addDays(minDate, -7), "end": addDays(maxDate, 7)};
}

def:pub getDefaultStartDate(dueDate: object) -> object {
    return startOfDay(dueDate);
}

def:pub getDefaultDueDate(startDate: object) -> object {
    return endOfDay(startDate);
}

def:pub isValidDateRange(startDate: object, dueDate: object) -> bool {
    return differenceInDays(startOfDay(dueDate), startOfDay(startDate)) >= 0;
}

def:pub snapToGrid(date: object) -> object {
    return startOfDay(date);
}
