def:pub LabelButton(
    label: str | None = None,
    children: JsxElement | str | list[JsxElement] | None = None,
    onClick: Callable[[MouseEvent], None] = lambda (_e: MouseEvent) { },
    disabled: bool = False,
    ariaLabel: str | None = None,
    className: str | None = None,
) -> JsxElement {
