def getYearBoost(queryYear: str | None, candidateYear: str | None) -> float {
    if not queryYear or not candidateYear {
        return 0.0;
    }
    if queryYear == candidateYear {
        return 12.0;
    }
    try {
        query_year_num = float(queryYear);
        candidate_year_num = float(candidateYear);
    } except ValueError {
        return 0.0;
    }
    if not isfinite(query_year_num) or not isfinite(candidate_year_num) {
        return 0.0;
    }
    year_distance = abs(query_year_num - candidate_year_num);
    if year_distance == 1.0 {
        return 6.0;
    }
    if year_distance == 2.0 {
        return 3.0;
    }
    return 0.0;
