import random;


def default[T]() -> Callable[[list[T]], list[T]] {
    def onShuffleArray(array: list[T]) -> list[T] {
        currentIndex: int = len(array);
        while currentIndex != 0 {
            randomIndex: int = int(random.random() * currentIndex);
            currentIndex -= 1;
            temporaryValue: T = array[currentIndex];
            array[currentIndex] = array[randomIndex];
            array[randomIndex] = temporaryValue;
        }
        return array;
    }
    return onShuffleArray;
}
