        htmlFor={htmlFor}
        className={cn(
          formLabelVariants({ size }),
          isDisabled && 'opacity-50 cursor-not-allowed',
          className
        )}
        {...props}
      >
        {children}
        {isRequired && showRequired && (
          <span className="ml-0.5 text-danger" aria-hidden="true">
            {requiredIndicator}
          </span>
        )}
      </label>
    );
  }
);

