def resolveSchema(schema: any) -> any {
    anyOf = schema.anyOf;
    if (anyOf and (len(anyOf) > 0)) {
        nonNull = anyOf.find(lambda (s: any) -> any { return ((s.type != "null") and (s.type != undefined)); });
        if nonNull {
            return {**schema, **nonNull, "anyOf": undefined};
        }
    }
    oneOf = schema.oneOf;
    if (oneOf and (len(oneOf) > 0)) {
        nonNull = oneOf.find(lambda (s: any) -> any { return ((s.type != "null") and (s.type != undefined)); });
        if nonNull {
            return {**schema, **nonNull, "oneOf": undefined};
        }
    }
    return schema;
}

