import from "@ninetailed/experience.js-shared" { getByPath, Profile }

def _join_selector_parts(dot_path: str, underscore_path: str) -> str {
    parts = [part for part in [dot_path, underscore_path] if part != ""];
    return ".".join(parts);
}

def:pub generateSelectors(id: str) -> list[str] {
    paths = id.split("_");
    return [
        _join_selector_parts(".".join(paths[0:i]), "_".join(paths[i:]))
        for i in range(len(paths))
    ];
}

def:pub selectValueFromProfile(profile: Profile, id: str) -> object | None {
    selectors = generateSelectors(id);
    matching_selector: str | None = None;
    for selector in selectors {
        if getByPath(profile, selector) {
            matching_selector = selector;
            break;
        }
    }
    if matching_selector is None {
        return None;
    }
    return getByPath(profile, matching_selector);
}
