obj Store {
    has initial_state: dict[str, object];
    has state: dict[str, object] postinit;
    has subscribers: list[Callable[[dict[str, object]], None]] = [];

    def postinit {
        self.state = {**self.initial_state};
        self.subscribers = [];
    }

    def getState() -> dict[str, object] {
        return self.state;
    }

    def setState(newState: dict[str, object]) -> None {
        self.state = {**self.state, **newState};
        for subscriber in self.subscribers {
            subscriber(self.state);
        }
    }

    def subscribe(callback: Callable[[dict[str, object]], None]) -> Callable[[], None] {
        self.subscribers.append(callback);
        return lambda {
            index = self.subscribers.index(callback);
            if index > -1 {
                _ = self.subscribers.pop(index);
            }
        };
    }
}
