const ListMarker = ({
  fontSize,
  color,
  tabCount,
  kind,
  leadItemIndex,
} : {
  fontSize: string,
  color: string,
  tabCount: number,
  kind: ListMarkerKind,
  leadItemIndex?: number | null,
}) => {
  if (kind === "none") return

  const tabNum = tabCount % 3 + 1

  return (
    <div
      className="rsc-li-marker"
      style={{
        paddingRight: `calc(${fontSize} / 2)`,
        marginLeft: `calc(${fontSize} * ${tabCount})`,
      }}
    >
      {tabCount > 0 ? (
        <ListDotMarker
          tabNum={tabNum}
          fontSize={fontSize}
          color={color}
        />
      ) : (
        <>
        {kind === "dot" && (
          <ListDotMarker
            tabNum={tabNum}
            fontSize={fontSize}
            color={color}
          />
        )}
        {kind === "number" && (
          <p
            className="rsc-li-num"
            style={{
              fontSize: fontSize,
              color: color,
            }}
          >
            {leadItemIndex}.
          </p>
        )}
        </>
      )}
    </div>
  )
}

const ListDotMarker = ({
  tabNum,
  fontSize,
  color,
} : {
  tabNum: number,
  fontSize: string,
  color: string,
}) => {
  return (
    <div
      className={`rsc-li-dot-${tabNum}`}
      style={{
        width: `calc(${fontSize} / 3)`,
        backgroundColor: tabNum !== 3 ? color : "",
        borderColor: color,
      }}
    />
  )
}
