def:pub LightenDarkenColor(col: str, amt: int) -> str {
    usePound = False;
    if col[0] == '#' {
        col = col[1:];
        usePound = True;
    }
    num = int(col, 16);
    r = (num >> 16) + amt;
    if r > 255 {
        r = 255;
    } elif r < 0 {
        r = 0;
    }
    b = ((num >> 8) & 0x00FF) + amt;
    if b > 255 {
        b = 255;
    } elif b < 0 {
        b = 0;
    }
    g = (num & 0x0000FF) + amt;
    if g > 255 {
        g = 255;
    } elif g < 0 {
        g = 0;
    }
    combined = g | (b << 8) | (r << 16);
    return ('#' if usePound else '') + format(combined, 'x');
}
