interface LContextData {
  namespace: string;
  componentDisabled: boolean;
  componentSize: Size;
  componentDefaultProps: { [K in keyof ComponentProps]?: Partial<ComponentProps[K]> };
  layoutPageScrollEl: RefExtra | null;
  layoutContentResizeEl: RefExtra | null;
