def button_class(active: bool = False) -> str {
    base = "p-1.5 rounded transition-colors ";
    if active {
        return base + "bg-accent-primary/10 text-accent-primary";
    }
    return base + "text-text-light-secondary dark:text-text-dark-secondary hover:bg-surface-light-alt dark:hover:bg-surface-dark-elevated";
