import from "@/lib/tailwind/utils" { cn }
import from "./Input" { Input, inputVariants }

glob SYMBOLS: dict[str, str | list[str]] = {"zero": "0", "negative": "-", "plus": "+", "e": ["e", "E"], "dot": "."};

obj ExceptionSymbolsProps {
    has exceptDot: bool = False;
    has exceptE: bool = True;
    has exceptLeadingZero: bool = True;
    has exceptNegative: bool = True;
    has exceptPlusOperator: bool = True;
}

def handleExceptionSymbols(event: KeyboardEvent, exceptionSymbolsProps: ExceptionSymbolsProps) {
    key = event.key;
    currentValue = (event.currentTarget as HTMLInputElement).value;
    dot = SYMBOLS["dot"] as str;
    zero = SYMBOLS["zero"] as str;
    negative = SYMBOLS["negative"] as str;
    plus = SYMBOLS["plus"] as str;
    eKeys = SYMBOLS["e"] as list[str];
    if (((((exceptionSymbolsProps.exceptDot and (key == dot)) or (exceptionSymbolsProps.exceptE and (key in eKeys))) or ((exceptionSymbolsProps.exceptLeadingZero and (key == zero)) and (currentValue == zero))) or (exceptionSymbolsProps.exceptNegative and (key == negative))) or (exceptionSymbolsProps.exceptPlusOperator and (key == plus))) {
        event.preventDefault();
    }
}

glob defaultVariant: str = "rounded";

glob defaultExceptionSymbols = ExceptionSymbolsProps();

def:pub NumberInput(
    className: str | None = None,
