    if (!('hidden' in variant)) {
      // Yeay! It correctly inferred the type of the property "foo" on the variant
      if ('foo' in variant) {
        expect(variant.foo).toBe('bar');
      }
    }
    expect(mapped.components[0].variants).toStrictEqual([
      { id: 'variant', foo: 'bar' },
    ]);
  });
});
