import re;

def:pub resolveChannelConfigValue(configForm: dict[str, object] | None, channelId: str) -> dict[str, object] | None {
    if configForm is None {
        return None;
    }
    channels = configForm.get("channels");
    if not isinstance(channels, dict) {
        return None;
    }
    val = channels.get(channelId);
    if isinstance(val, dict) {
        return val as dict[str, object];
    }
    return None;
}

def:pub humanizeKey(key: str) -> str {
    result = re.sub(r"([a-z])([A-Z])", r"\1 \2", key);
    result = re.sub(r"([A-Z]+)([A-Z][a-z])", r"\1 \2", result);
    if result {
        return result[0].upper() + result[1:];
    }
    return result;
}
