		const timer = window.setTimeout(
			() => setUtcDay(currentUtcDay),
			Math.max(1_000, msUntilRollover),
		);
		return () => window.clearTimeout(timer);
	}, [utcDay]);

	return useQuery(api.profile.mine, enabled ? { today: utcDay } : "skip");
