// anonymous cold load shows a blank page until that round trip returns.
function LoginPagePending() {
  return (
    <LoginCardShell>
      <div className="space-y-4">
        <div className="space-y-2">
          <Skeleton className="h-4 w-16" />
          <Skeleton className="h-9 w-full" />
        </div>
        <div className="space-y-2">
