/**
 * 用单独的组件容纳 useRoutes 返回的内容。因为 useRoutes 会随着路由的变动而触发
 * 当前组件重新渲染，这样做可以最小化减少重新渲染的内容。
 */
export function RouteTree({ data }: { data: RouteObject[] }) {
