    if userCoins < priceVal {
        return {"error": "Not enough coins"};
    }
    try {
        player = {"id": userId};
        if not player {
            return {"error": "Error deducting coins."};
        }
        upgrade = {"id": upgradeId if upgradeId is not None else "", "purchased": True};
        if not upgrade {
            return {"error": "Error updating upgrade.purchased to true."};
