function isSendKey(event: React.KeyboardEvent) {
	return event.key === "Enter" && !event.shiftKey;
}

function isModifierSendKey(event: React.KeyboardEvent) {
	return (event.metaKey || event.ctrlKey) && event.key === "Enter";
