          ? [...current[Number(key)]]
          : { ...current[Number(key)] };
        current = current[Number(key)];
      }
    } else {
      // Object key
      if (typeof current[key] !== "object" || current[key] === null) {
        current[key] = {};
      } else {
        current[key] = Array.isArray(current[key])
          ? [...current[key]]
          : { ...current[key] };
      }
      current = current[key];
    }
