}));

const makeGroup = (ruleId: string, violationCount: number, startIndex = 0): ScanGroup => ({
  ruleId,
  violations: Array.from({ length: violationCount }, (_, i) => ({
    index: startIndex + i,
    selector: `div.item-${startIndex + i}`,
    warnings: [
      {
        ruleId,
        property: 'width',
        severity: 'warning' as const,
        title: 'No-op',
        details: 'Details',
        suggestion: 'Suggestion',
      },
    ],
  })),
});

const groups: ScanGroup[] = [];
const status: ScanStatus = 'idle';
const error: string | null = null;
const inspectError: string | null = null;
const progress: ScanProgress = { scanned: 0, total: 0 };

