 * Layout Class Mappings
 * Shared gap, grid, and flex Tailwind class mappings
 */
import type {
  GapSize,
  GridColumns,
  GridRows,
  FlexDirection,
  FlexAlign,
  FlexJustify,
  FlexWrap,
  ResponsiveValue,
} from '../tokens';

/** Gap size class mappings */
export const GAP_SIZES: Record<GapSize, string> = {
  '0': 'gap-0',
  '1': 'gap-1',
  '2': 'gap-2',
  '3': 'gap-3',
