  providers: ModelProvider[];
}

export interface ModelInfo {
  model: string;
  provider: string;
  capabilities: ModelCapabilities;
}

export interface AuxiliaryModel {
  task: string;
  provider: string;
  model: string;
  base_url?: string;
}

