        .filter((coinCategory: CoinCategory) => coinCategory.categoryId !== 'recently_added')

    cacheWithExpiry('coinCategories', normalizedResponse, 8.64e+7);  // Cache Period: 1 day

    return normalizedResponse as CoinCategory[]
  }
