import from "@radix-ui/react-slot" { Slot }
import from ...lib.utils { cn }
import from .separator { Separator }

glob BUTTON_GROUP_BASE: str = "flex w-fit items-stretch has-[>[data-slot=button-group]]:gap-2 [&>*]:focus-visible:relative [&>*]:focus-visible:z-10 has-[select[aria-hidden=true]:last-child]:[&>[data-slot=select-trigger]:last-of-type]:rounded-r-md [&>[data-slot=select-trigger]:not([class*='w-'])]:w-fit [&>input]:flex-1";

glob BUTTON_GROUP_ORIENTATION_CLASSES: dict[str, str] = {
    "horizontal": "[&>*:not(:first-child)]:rounded-l-none [&>*:not(:first-child)]:border-l-0 [&>*:not(:last-child)]:rounded-r-none",
    "vertical": "flex-col [&>*:not(:first-child)]:rounded-t-none [&>*:not(:first-child)]:border-t-0 [&>*:not(:last-child)]:rounded-b-none",
};

def:pub buttonGroupVariants(orientation: str | None = None, className: str | None = None) -> str {
    o = orientation or "horizontal";
    return cn(BUTTON_GROUP_BASE, BUTTON_GROUP_ORIENTATION_CLASSES.get(o, ""), className);
}

def:pub ButtonGroup(
    className: str | None = None,
    orientation: str | None = None,
    props: dict[str, object] = {},
) -> JsxElement {
    <div
        role="group"
        data-slot="button-group"
        data-orientation={orientation or "horizontal"}
        className={buttonGroupVariants(orientation=orientation, className=className)}
        {**props}
    />
}

glob BUTTON_GROUP_TEXT_BASE: str = "bg-muted shadow-xs flex items-center gap-2 rounded-md border px-4 text-sm font-medium [&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none";

def:pub ButtonGroupText(
    className: str | None = None,
    asChild: bool = False,
    props: dict[str, object] = {},
    children: object | None = None,
) -> JsxElement {
    classes = cn(BUTTON_GROUP_TEXT_BASE, className);
    if asChild {
        return <Slot className={classes} {**props}>{children}</Slot>;
    }
    return <div className={classes} {**props}>{children}</div>;
}

glob BUTTON_GROUP_SEPARATOR_BASE: str = "bg-input relative !m-0 self-stretch data-[orientation=vertical]:h-auto";

def:pub ButtonGroupSeparator(
    className: str | None = None,
    orientation: str | None = None,
    props: dict[str, object] = {},
) -> JsxElement {
  <Separator
        data-slot="button-group-separator"
        orientation={orientation or "vertical"}
        className={cn(BUTTON_GROUP_SEPARATOR_BASE, className)}
        {**props}
    />
}
