import from "react" { useEffect, useRef }
import from "classnames" { default as classnames }

def:pub Modal(
    children: object | None = None,
    maxWidth: str = "lg",
    onClickOutside: Callable[[], None] | None = None
) -> JsxElement {
    contentEl = useRef(None);

    useEffect(lambda {
        def listener(e: MouseEvent) {
            el = contentEl.current;
            if el and not el.contains(e.target) {
                if onClickOutside {
                    onClickOutside();
                }
            }
        }
        document.addEventListener("click", listener);
        return lambda {
            document.removeEventListener("click", listener);
        };
