    return f"{colLabel}{ri + 1}";
}

def:pub xyFromLabel(label: str) -> tuple[int, int] {
    x = "";
    y = "";
    i = 0;
    while i < len(label) {
        ch = label[i];
        if ch >= "0" and ch <= "9" {
            y += ch;
        } else {
            x += ch;
        }
        i += 1;
    }
    return (colIndexFromLabel(x), int(y) - 1);
}
