def toSubjectResponse(subject: Subject) -> SubjectResponse {
    data = subject.toJSON();
    return SubjectResponse(
        subject_id=data["subject_id"] as str,
        name=data["name"] as str,
    );
}

obj SubjectService {
    static async def createSubject(subjectId: str, name: str) -> SubjectResponse {
        subject = await Subject.create(subject_id=subjectId, name=name);
        return toSubjectResponse(subject);
    }

    static async def getSubjects() -> list[SubjectResponse] {
        subjects = await Subject.findAll();
        return [toSubjectResponse(subject) for subject in subjects];
    }

    static async def getSubject(subjectId: str) -> SubjectResponse | None {
        subject = await Subject.findByPk(subjectId);
        if subject is None {
            return None;
        }
        return toSubjectResponse(subject);
    }

    static async def updateSubject(subjectId: str, updates: SubjectUpdateData) -> bool {
        updateData: dict[str, str] = {};
        if updates.name is not None {
            updateData["name"] = updates.name;
        }
        result = await Subject.update(updateData, where={"subject_id": subjectId});
        affectedCount = result[0] as int;
        return affectedCount > 0;
    }

    static async def deleteSubject(subjectId: str) -> DeleteSubjectResponse {
        deletionErrors: list[str] = [];

        try {
            await QuestionService.deleteQuestionsBySubject(subjectId);
        } except Exception as error {
            deletionErrors.append(f"Failed to delete questions: {str(error)}");
        }

        try {
            Embedding.deleteEmbeddingsBySubject(subjectId);
        } except Exception as error {
            deletionErrors.append(f"Failed to delete embeddings: {str(error)}");
        }

        try {
            await FileService.deleteFilesBySubject(subjectId);
        } except Exception as error {
            deletionErrors.append(f"Failed to delete files: {str(error)}");
        }

        try {
            await Subject.destroy(where={"subject_id": subjectId});
            return DeleteSubjectResponse(
                deletionErrors=deletionErrors if len(deletionErrors) > 0 else None,
            );
        } except Exception as error {
            deletionErrors.append(f"Failed to delete subject: {str(error)}");
            return DeleteSubjectResponse(deletionErrors=deletionErrors);
        }
    }
}
