  return useCallback(
    (
      file: FileToOpen,
      options?: { x?: number; y?: number },
    ): void => {
      const fileType = getFileTypeKind(file);

      if (fileType.kind === "image") {
        void startCenteredApp(
          startImagePreview({
            fileId: file._id,
            fileName: file.name,
            x: options?.x,
            y: options?.y,
          }),
        );
        return;
      }
      if (fileType.kind === "video") {
        void startCenteredApp(
          startVideoPlayer({
            fileId: file._id,
            fileName: file.name,
            x: options?.x,
            y: options?.y,
          }),
