    props: dict[str, object] | None = None,
) -> JsxElement {
    valueVal = value if value is not None else "info";
    sizeVal = size if size is not None else "md";
    extra = props if props is not None else {};
    <div
        ref={ref}
        data-slot="status"
        role="status"
        aria-label={None if children else f"Status: {valueVal}"}
        className={cn(STATUS_ROOT_CLASS, className)}
        {**extra}
    >
        <span
            data-slot="indicator"
            className={cn(statusIndicatorVariants(value=valueVal, size=sizeVal))}
            aria-hidden="true"
        />
        {children and <span data-slot="label" className={cn(statusLabelVariants(value=valueVal, size=sizeVal))}>{children}</span>}
    </div>
}
