import from utils { isFunction }

type MiddlewareAction = Callable[[object], object | None];
type MiddlewareNext = Callable[[], object | None];
type IMiddleware = Callable[[MiddlewareAction, MiddlewareNext], object | None];

def compose(middlewares: list[IMiddleware]) -> Callable[[object, MiddlewareNext | None], object | None] {
    for fn in middlewares {
        if not isFunction(fn) {
            raise TypeError("All Middlewares must be composed of functions!");
        }
    }
    def composed(action_arg: object, next: MiddlewareNext | None = None) -> object | None {
        index: int = -1;
        def dispatch(i: int) -> object | None {
            if i <= index {
                raise RuntimeError("next() called multiple times");
            }
            index = i;
            current: IMiddleware | MiddlewareNext | None = None;
            if i == len(middlewares) {
                current = next;
            } else {
                current = middlewares[i];
            }
            if current is None {
                return None;
            }
            return current(action_arg, lambda { dispatch(i + 1) });
        }
        return dispatch(0);
    }
    return composed;
}
