    has signedAtMs: int;
    has token: str | None = None;
    has nonce: str | None = None;
    has version: str | None = None;
}

def buildDeviceAuthPayload(params: DeviceAuthPayloadParams) -> str {
    version = params.version if params.version is not None else ("v2" if params.nonce else "v1");
    scopes = ",".join(params.scopes);
    token = params.token if params.token is not None else "";
    base: list[str] = [
        version,
        params.deviceId,
        params.clientId,
        params.clientMode,
        params.role,
        scopes,
        str(params.signedAtMs),
        token,
    ];
    if version == "v2" {
        base.append(params.nonce if params.nonce is not None else "");
    }
    return "|".join(base);
}
