def:pub toArabicNumeral(en: int | str) -> str {
    arabic_digits = "٠١٢٣٤٥٦٧٨٩";
    result = "";
    for ch in str(en) {
        if ch.isdigit() {
            result += arabic_digits[int(ch)];
        } else {
            result += ch;
        }
    }
    return result;
}
