import from time { time as time_now }

glob UNITS: list[dict[str, float | str]] = [
    {"limit": 60.0, "div": 1.0, "label": "second"},
    {"limit": 3600.0, "div": 60.0, "label": "minute"},
    {"limit": 86400.0, "div": 3600.0, "label": "hour"},
    {"limit": 604800.0, "div": 86400.0, "label": "day"},
    {"limit": 2629800.0, "div": 604800.0, "label": "week"},
    {"limit": 31557600.0, "div": 2629800.0, "label": "month"},
    {"limit": float('inf'), "div": 31557600.0, "label": "year"},
];

def:pub relativeTime(timestampSec: int | None) -> str {
    if not timestampSec {
        return "unknown";
    }
    diff = max(0, int(time_now() - timestampSec));
    if diff < 5 {
        return "just now";
    }
    unit: dict[str, float | str] | None = None;
    for u in UNITS {
        if diff < (u["limit"] as float) {
            unit = u;
            break;
        }
    }
    if not unit {
        return "unknown";
    }
    value = int((diff as float) / (unit["div"] as float));
    label = unit["label"] as str;
    suffix = "" if value == 1 else "s";
    return f"{value} {label}{suffix} ago";
}
