/**
 * A compiler for when-clauses.
 */
class WhenClauseCompiler {
  private cache = new Map<string, When>();

  compile(whenClause: string | undefined | null): When | undefined {
    if (!whenClause) {
      return undefined;
    }
    const cachedWhenFn = this.cache.get(whenClause);
    if (cachedWhenFn) {
