    return (
      megaContext.showMegaLevelCaps &&
      megaContext.isMasterLeague &&
      megaContext.isMegaSpecies &&
      levelCaps[MEGA_LEVEL_CAP_BASE[level]]
    );
  }

  return levelCaps[level];
}

