export interface FieldAriaInput {
  fieldId: string;
  error?: unknown;
  touched?: unknown;
  required?: boolean;
}
export interface FieldAriaResult {
  "aria-invalid"?: true;
  "aria-describedby"?: string;
  "aria-required"?: true;
  errorId: string;
}
/** ARIA props for an input + the id its error element should carry. */
export function fieldAriaProps({
  fieldId,
  error,
  touched,
  required,
}: FieldAriaInput): FieldAriaResult {
  const showError = Boolean(touched && error);
  const errorId = `${fieldId}-error`;
  return {
    ...(showError
      ? { "aria-invalid": true as const, "aria-describedby": errorId }
      : {}),
    ...(required ? { "aria-required": true as const } : {}),
    errorId,
  };
}
```

```jac
def:pub fieldAriaProps(input: dict[str, object]) -> dict[str, object] {
    fieldId = input["fieldId"] as str;
    error = input.get("error");
    touched = input.get("touched");
    required = bool(input.get("required"));
    showError = bool(touched and error);
    errorId = f"{fieldId}-error";
    return {
        **({"aria-invalid": True, "aria-describedby": errorId} if showError else {}),
        **({"aria-required": True} if required else {}),
        "errorId": errorId
    };
}
