import from "react" { useCallback, useMemo }
import from "@/lib/url-filters" { applyFilterUpdate }

def:pub useUrlFilters(
    search: object,
    navigate: Callable[[dict[str, object]], None],
    decode: Callable[[object], object],
    encode: Callable[[object, object], object],
    resetOnChange: object | None = None,
) -> dict[str, object] {
    filters = useMemo(lambda -> object { return decode(search); }, [decode, search]);
    setFilters = useCallback(
        lambda (updater: Callable[[object], object]) {
            navigate({
                "search": lambda (prev: object) -> object {
                    return applyFilterUpdate(prev, updater, {"decode": decode, "encode": encode, "resetOnChange": resetOnChange});
                },
                "replace": True,
            });
        },
        [navigate, decode, encode, resetOnChange],
    );
    patchSearch = useCallback(
        lambda (patch: dict[str, object]) {
            navigate({"search": lambda (prev: object) -> object { return {**prev, **patch}; }, "replace": True});
        },
        [navigate],
    );
    return {"filters": filters, "setFilters": setFilters, "patchSearch": patchSearch};
}
