        return 'market_cap'
      case 'totalVolume':
        return 'volume'
    }
    return 'market_cap'
  };

  const createSortHandler = (property: keyof Coin) => (event: React.MouseEvent<unknown>) => {
    onRequestSort(event, idToSort(property));
  };

