    switch (sortingKey) {
      case 'market_cap':
        return 'marketCap'
      case 'volume':
        return 'totalVolume'
    }
  };

  const sortingId = sortToId(orderBy);

  return (
    <TableHead className={classes.root}>
      <TableRow>
        {headCells
        .filter((headCell: CoinListTableHeadCell) => 
        coinList.coinListTableColumns.includes(headCell.id) || !headCell.customisable)
        .map((headCell: CoinListTableHeadCell, index: number) => (
          <TableCell
            key={headCell.id}
            align={headCell.numeric ? 'right' : 'left'}
            sortDirection={sortingId === headCell.id ? order : false}
            className={index < 2 ? classes.stickyColumn : undefined}
            style={{ left: index === 0 ? 0 : index === 1 ? 67 : 'auto' }}
          >
            <TableSortLabel
              disabled={headCell.id !== 'marketCap' && headCell.id !== 'totalVolume'}
              active={sortingId === headCell.id}
              direction={sortingId === headCell.id ? order : 'asc'}
              onClick={createSortHandler(headCell.id)}
            >
              <Typography variant="subtitle2" noWrap>
                {headCell.label}
              </Typography>
            </TableSortLabel>
          </TableCell>
        ))}
      </TableRow>
    </TableHead>
  );
}

export default CoinListTableHeader
