            cy="32"
            r="28"
            fill="none"
            stroke="url(#gradient)"
            strokeWidth="2"
            strokeLinecap="round"
            initial={{ pathLength: 0 }}
            animate={{
              pathLength:
                (sections.indexOf(activeSection) + 1) / sections.length,
