            className="absolute inset-0 bg-gradient-to-r from-rose-400/30 to-pink-400/30 rounded-full"
            initial={{ scale: 0, opacity: 0 }}
            whileTap={{ scale: 2, opacity: [0, 0.3, 0] }}
