import from "twilio-video" { LocalVideoTrack, RemoteVideoTrack }

type TrackType = RemoteVideoTrack | LocalVideoTrack | None;

def:pub useIsTrackSwitchedOff(track: TrackType) -> bool {
    has is_switched_off: bool = track.isSwitchedOff if track else False;

    useEffect(lambda {
        if track {
            current = track;
            is_switched_off = current.isSwitchedOff;
            def handle_switched_off {
                is_switched_off = True;
            }
            def handle_switched_on {
                is_switched_off = False;
            }
            current.on("switchedOff", handle_switched_off);
            current.on("switchedOn", handle_switched_on);
            return lambda {
                current.off("switchedOff", handle_switched_off);
                current.off("switchedOn", handle_switched_on);
            };
        }
        is_switched_off = False;
    }, [track]);

    return bool(is_switched_off);
}
