import math;

def:pub niceCeil(x: float) -> float {
    base = 10 ** math.floor(math.log10(x));
    step: float = 10;
    for s in [1, 2, 2.5, 5, 10] {
        if (x / base <= s) {
            step = s;
            break;
        }
    }
    return step * base;
}

def:pub clampedYMax(values: list[float | None]) -> float | None {
    finite = [v for v in values if isinstance(v, (int, float)) and math.isfinite(v)];
    if len(finite) < 6 {
        return None;
    }
    sorted_vals = sorted(finite);
    spike_count = max(1, math.floor(len(sorted_vals) * 0.02));
    reference = sorted_vals[len(sorted_vals) - 1 - spike_count];
    max_val = sorted_vals[len(sorted_vals) - 1];
    if reference <= 0 or max_val <= reference * 2.5 {
        return None;
    }
    clamped = niceCeil(reference * 1.2);
    if clamped < max_val {
        return clamped;
    }
    return None;
}
