  css: string;
  enabled: boolean;
  lastUpdated: string;
}

interface CustomCSSActions {
  updateCSS: (css: string) => void;
  toggleEnabled: () => void;
  resetCSS: () => void;
}

type CustomCSSStore = CustomCSSState & CustomCSSActions;

