        self.handlers[type] = callback;
    }

    def getRequestHandler(type: str | None = None) -> RequestHandler {
        if type and type in self.handlers {
            return self.handlers[type];
        }
        return defaultRequestHandler;
    }

    def handleRequest(request: RequestMessage = RequestMessage(), sendResponse: SendResponse = log) {
        handle = self.getRequestHandler(request.type);
        handle(request, sendResponse);
    }
}

