import type from shared.types { NormalizedDynamicBookmark }

def getBreadcrumbIds(nodes: dict[str, NormalizedDynamicBookmark] | None = None, id: str = "0") -> list[str] {
    nodeMap = nodes if nodes is not None else {};
    breadcrumbs: list[str] = [];
    currId = id;
    while currId != "" {
        breadcrumbs.append(currId);
        currNode = nodeMap.get(currId);
        if currNode is None {
            currId = "";
        } else {
            parentId = currNode.parentId;
            currId = parentId if parentId is not None else "";
        }
    }
    return list(reversed(breadcrumbs));
}

