        } elif lowerPart.startswith("date:") and len(part) > 5 {
            value = part[5:].lower();
            if value in VALID_DATES {
                filters.append(SearchFilter(type="date", value=value));
            } else {
                textParts.append(part);
            }
        } else {
            textParts.append(part);
        }
    }
    return ParsedSearchQuery(text=" ".join(textParts).strip(), filters=filters);
