    readonly facetType: FacetTypeEnum = FacetTypeEnum.NumericFacet;

    @computed
    get values(): number[] { return this._values; };

    @computed
    get minValue(): number { return this._minValue; };

    @computed
    get maxValue(): number { return this._maxValue; };

