/**
 * For object `{A:{propA}, B:{propB}}` and `{A:{propA2}, C:{propC}}` returns `{A:{propA, propA2}, B:{propB}, C:{propC}}`
 */
export function combineProps(lhs = {}, rhs = {}) {
  return {
    ...lhs,
    ...rhs,
    ..._combineCommonProps(lhs, rhs),
  };
}

/**
 * For object `{A:{propA}, B:{propB}}` and `{A:{propA2}, C:{propC}}` returns `{A:{propA, propA2}}`
 */
function _combineCommonProps(lhs = {}, rhs = {}) {
  const retVal = {};
  for (const key in lhs) {
    if (!(key in rhs)) {
      continue;
    }
    retVal[key] = {
      ...lhs[key],
      ...rhs[key],
    };
  }
  return retVal;
}
export default combineProps;
```

```jac
def:pub combineProps(
    lhs: dict[str, dict[str, object]] | None = None,
    rhs: dict[str, dict[str, object]] | None = None
) -> dict[str, object] {
    if lhs is None {
        lhs = {};
    }
    if rhs is None {
        rhs = {};
    }
    return {**lhs, **rhs, **_combineCommonProps(lhs, rhs)};
}

def _combineCommonProps(
    lhs: dict[str, dict[str, object]],
    rhs: dict[str, dict[str, object]]
) -> dict[str, dict[str, object]] {
    retVal: dict[str, dict[str, object]] = {};
    for key in lhs {
        if key not in rhs {
            continue;
        }
        retVal[key] = {**lhs[key], **rhs[key]};
    }
    return retVal;
}
