glob BUTTON_SIZE_CLASSES: dict[str, str] = {
    "default": "h-11 px-5 py-2",
    "sm": "h-11 rounded-md px-4 text-sm",
    "lg": "h-12 rounded-md px-8",
    "icon": "h-11 w-11",
    "icon-sm": "h-11 w-11 [&_svg]:size-4",
};

def:pub buttonVariants(
    variant: str | None = None,
    size: str | None = None,
    className: str | None = None,
) -> str {
    v = variant or "default";
    s = size or "default";
    return cn(BUTTON_BASE, BUTTON_VARIANT_CLASSES.get(v, ""), BUTTON_SIZE_CLASSES.get(s, ""), className);
}

def:pub Button(
    className: str | None = None,
    variant: str | None = None,
    size: str | None = None,
    asChild: bool = False,
    ref: Ref[HTMLButtonElement] = Ref(),
    props: dict[str, object] = {},
    children: object | None = None,
) -> JsxElement {
    classes = cn(buttonVariants(variant=variant, size=size, className=className));
    if asChild {
        return <Slot className={classes} ref={ref} {**props}>{children}</Slot>;
    }
    return <button className={classes} ref={ref} {**props}>{children}</button>;
}
