        if self.set_state is not None {
            self.set_state(self.notifications);
        }
    }

    def remove(id: str) {
        self.notifications = [n for n in self.notifications if n.id != id];
        if self.set_state is not None {
            self.set_state(self.notifications);
        }
    }

    def get() -> list[NotificationData] {
        return self.notifications;
