def buttonVariants(
    variant: str | None = None,
    color: str | None = None,
    size: str | None = None,
    radius: str | None = None,
    fullWidth: bool = False,
) -> str {
    v = variant if variant is not None else "solid";
    c = color if color is not None else "primary";
    s = size if size is not None else "md";
