def drownPathAndTriangle(
    taskFrom: BarTask,
    taskTo: BarTask,
    rowHeight: float,
    taskHeight: float,
    arrowIndent: float
) -> list[str] {
    indexCompare = -1 if (taskFrom.index > taskTo.index) else 1;
    taskToEndPosition = taskTo.y + 10 + (taskHeight / 2);
    taskFromEndPosition = taskFrom.x2 + (arrowIndent * 2);
    taskFromHorizontalOffsetValue = "" if (taskFromEndPosition < taskTo.x1) else f"H {taskTo.x1 - arrowIndent}";
    taskToHorizontalOffsetValue = arrowIndent if (taskFromEndPosition > taskTo.x1) else (taskTo.x1 - taskFrom.x2 - arrowIndent);
    path = f"M {taskFrom.x2} {taskFrom.y + 10 + (taskHeight / 2)}\n  h {arrowIndent}\n  v {(indexCompare * rowHeight) / 2}\n  {taskFromHorizontalOffsetValue}\n  V {taskToEndPosition}\n  h {taskToHorizontalOffsetValue}";
    trianglePoints = f"{taskTo.x1},{taskToEndPosition}\n  {taskTo.x1 - 5},{taskToEndPosition - 5}\n  {taskTo.x1 - 5},{taskToEndPosition + 5}";
    return [path, trianglePoints];
}

