                        <span>
                          {format(start, "h:mm a")} - {format(end, "h:mm a")}
                        </span>
                      </div>
                    </div>
                  </div>
                </button>
              );
            })}
          </div>
        ) : (
          <p className="text-center text-xs italic text-muted-foreground">
            No events currently in progress
          </p>
        )}
      </div>

      {/* Upcoming Events Section */}
      {upcomingEvents.length > 0 && (
