        if i >= 48.5 {
            xlCandy += 20;
        } elif i >= 46.5 {
            xlCandy += 17;
        } elif i >= 44.5 {
            xlCandy += 15;
        } elif i >= 42.5 {
            xlCandy += 12;
        } else {
