def restaurant_nav_icon(path: str) -> JsxElement {
    if path == "/restaurant" {
        return <span className="w-5 h-5 inline-block text-center">📊</span>;
    }
    if path == "/restaurant/orders" {
        return <span className="w-5 h-5 inline-block text-center">🛍️</span>;
    }
    if path == "/restaurant/menu" {
        return <span className="w-5 h-5 inline-block text-center">🍴</span>;
    }
    if path == "/restaurant/reports" {
        return <span className="w-5 h-5 inline-block text-center">📄</span>;
    }
    return <span className="w-5 h-5 inline-block text-center">⚙️</span>;
}

def:pub RestaurantDashboard() -> JsxElement {
    nav = useNavigate();
    location = useLocation();
    has user: dict[str, str] | None = None;
    has restaurant: dict[str, str] | None = None;

    can with entry {
        userData = localStorage.getItem("user");
        if not userData {
            nav("/login");
        } else {
            user = JSON.parse(userData) as dict[str, str];
            restaurant = {"name": "Demo Restaurant", "slug": "demo-restaurant"};
        }
    }

    def handle_logout(e: MouseEvent) {
        localStorage.removeItem("user");
        nav("/login");
    }

    if not user {
        return <></>;
    }

    navItems = [
        {"path": "/restaurant", "label": "Dashboard"},
        {"path": "/restaurant/orders", "label": "Orders"},
        {"path": "/restaurant/menu", "label": "Menu"},
        {"path": "/restaurant/reports", "label": "Reports"},
        {"path": "/restaurant/settings", "label": "Settings"},
    ];

    <div className="min-h-screen bg-bg-subtle">
        <nav className="bg-white border-b border-border sticky top-0 z-40">
            <div className="container-custom">
                <div className="flex items-center justify-between h-16">
                    <div className="flex items-center space-x-3">
                        <span className="w-8 h-8 text-accent text-2xl leading-none">🏪</span>
                        <div>
                            <h1 className="text-lg font-bold text-text">
                                {restaurant["name"] if restaurant else "Restaurant"}
                            </h1>
                            <p className="text-xs text-text-secondary">{user["email"]}</p>
                        </div>
                    </div>
                    <button onClick={handle_logout} className="flex items-center space-x-2 text-text-secondary hover:text-error transition-colors">
                        <span className="w-5 h-5">🚪</span>
                        <span>Logout</span>
                    </button>
                </div>
            </div>
        </nav>
        <div className="bg-white border-b border-border">
            <div className="container-custom">
                <div className="flex space-x-1 overflow-x-auto">
                    {for item in navItems {
                        isActive = location.pathname == item["path"];
                        <Link
                            key={item["path"]}
                            to={item["path"]}
                            className={f"flex items-center space-x-2 px-4 py-3 border-b-2 transition-colors whitespace-nowrap {'border-accent text-accent font-medium' if isActive else 'border-transparent text-text-secondary hover:text-text'}"}
                        >
                            {restaurant_nav_icon(item["path"])}
                            <span>{item["label"]}</span>
                        </Link>
                    }}
                </div>
            </div>
        </div>
        <div className="container-custom py-8">
            <Routes>
                <Route index element={<RestaurantHome />} />
                <Route path="orders" element={<Orders />} />
                <Route path="menu" element={<Menu />} />
                <Route path="reports" element={<Reports />} />
                <Route path="settings" element={<RestaurantSettings />} />
            </Routes>
        </div>
    </div>
}
