def:pub useHasMultipleCameras() -> dict[str, bool] {
    has hasMultipleCameras: bool = False;

    async can with entry {
        media_devices = (window.navigator as dict[str, object])["mediaDevices"] as dict[str, object];
        devices = await media_devices["enumerateDevices"]();
        video_count = 0;
        for d in devices as list[dict[str, str]] {
