      <motion.span
        className="text-sm sm:text-base relative z-10"
        animate={isActive ? NAVIGATION_ANIMATIONS.icon.active : {}}
        transition={NAVIGATION_ANIMATIONS.icon.transition}
        whileHover={NAVIGATION_ANIMATIONS.icon.hover}
