const KEY = "buwan.homophones.v1";

export type HomophoneEntry = {
  en: string;
  hanzi: string;
  pinyin?: string;
  updatedAt: number;
};

function normKey(en: string): string {
  return en.trim().toLowerCase();
}

export function loadHomophones(): Record<string, HomophoneEntry> {
  if (typeof window === "undefined") return {};
  try {
    const raw = window.localStorage.getItem(KEY);
    if (!raw) return {};
    return JSON.parse(raw) as Record<string, HomophoneEntry>;
  } catch {
    return {};
  }
}

export function getHomophone(en: string): HomophoneEntry | null {
  const all = loadHomophones();
  return all[normKey(en)] ?? null;
}

export function saveHomophone(en: string, hanzi: string, pinyin?: string): void {
  if (typeof window === "undefined") return;
  const all = loadHomophones();
  const k = normKey(en);
  const trimmed = hanzi.trim();
  const trimmedPinyin = pinyin?.trim();
  if (!trimmed) {
    delete all[k];
  } else {
    all[k] = {
      en: en.trim(),
      hanzi: trimmed,
      ...(trimmedPinyin ? { pinyin: trimmedPinyin } : {}),
      updatedAt: Date.now(),
    };
  }
  window.localStorage.setItem(KEY, JSON.stringify(all));
  window.dispatchEvent(new Event("homophones-updated"));
}

export function deleteHomophone(en: string): void {
  saveHomophone(en, "");
}

export function listHomophones(): HomophoneEntry[] {
  return Object.values(loadHomophones()).sort((a, b) => b.updatedAt - a.updatedAt);
}
