      <Select value={activeTab.to} onValueChange={handleTabChange}>
        <SelectTrigger aria-label="Settings section" className="h-10 w-full sm:hidden">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {tabs.map((tab) => (
            <SelectItem key={tab.to} value={tab.to}>
