import from "@/lib/utils" { cn }

def:pub toggleVariants(variant: str = "default", size: str = "default", className: str = "") -> str {
    base = "inline-flex items-center justify-center gap-2 rounded-md text-sm font-medium cursor-pointer transition-colors hover:bg-muted hover:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 disabled:cursor-not-allowed data-[state=on]:bg-accent data-[state=on]:text-accent-foreground [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0";
    variant_cls = "bg-transparent";
    if variant == "outline" {
        variant_cls = "border border-input bg-transparent shadow-sm hover:bg-accent hover:text-accent-foreground";
    }
    size_cls = "h-9 px-2 min-w-9";
    if size == "sm" {
        size_cls = "h-8 px-1.5 min-w-8";
    } elif size == "lg" {
        size_cls = "h-10 px-2.5 min-w-10";
    }
    return cn(base, variant_cls, size_cls, className);
}

def _toggle_render(props: dict[str, object], ref: object | None = None) -> JsxElement {
    className = str(props.get("className") or "");
    variant = str(props.get("variant") or "default");
    size = str(props.get("size") or "default");
    rest: dict[str, object] = {};
    for (k, v) in props.items() {
        if k not in ["className", "variant", "size"] {
            rest[k] = v;
        }
    }
    <TogglePrimitive.Root
        ref={ref}
        className={cn(toggleVariants(variant=variant, size=size, className=className))}
        {**rest}
    />
}

glob:pub Toggle = forwardRef(_toggle_render);
